// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v, uint _decimals) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(0));
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }
        vm.assume(_decimals <= 77);
        (bool success, bytes memory data) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, caddress, _tos, v, _decimals));
        if (success) {
            bool result = abi.decode(data, (bool));
            assertTrue(result, "transfer should return true on success");
        }
    }
}

